import React from 'react';
import { Link } from 'react-router-dom';
import { 
  LayoutDashboard, Users, ShoppingBag, CreditCard, 
  BarChart3, MessageSquare, Settings, LogOut, User, Shield 
} from 'lucide-react';

const Sidebar = ({ sidebarOpen, location, onLogout }) => {
  const userEmail = localStorage.getItem('userEmail') || 'enzo@gmail.com';

  return (
    <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-white/95 dark:bg-neutral-900/95 backdrop-blur-xl border-r border-neutral-200/50 dark:border-neutral-800/50 transform transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
      <div className="flex flex-col h-full">
        {/* Logo */}
        <div className="p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
          <div className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <Shield className="h-6 w-6 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-neutral-900 dark:text-white">Admin<span className="text-primary-600 dark:text-primary-400">Pro</span></h1>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">Dashboard Premium</p>
            </div>
          </div>
        </div>

        {/* User Profile */}
        <div className="p-6 border-b border-neutral-200/50 dark:border-neutral-800/50">
          <div className="flex items-center space-x-3">
            <div className="h-12 w-12 rounded-xl bg-gradient-to-r from-primary-500 to-accent-500 flex items-center justify-center">
              <User className="h-6 w-6 text-white" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-neutral-900 dark:text-white truncate">
                Enzo Admin
              </p>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 truncate">
                {userEmail}
              </p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 p-4 overflow-y-auto">
          <ul className="space-y-2">
            <SidebarItem 
              to="/dashboard" 
              icon={<LayoutDashboard className="h-5 w-5" />}
              label="Tableau de bord"
              active={location.pathname === '/dashboard'}
            />
            <SidebarItem 
              to="/dashboard/users" 
              icon={<Users className="h-5 w-5" />}
              label="Utilisateurs"
              active={location.pathname === '/dashboard/users'}
              badge="42"
              badgeColor="accent"
            />
            {/* Ajouter les autres items de navigation */}
          </ul>

          {/* Quick Stats */}
          <div className="mt-8 p-4 rounded-xl bg-gradient-to-r from-neutral-50 to-white dark:from-neutral-800 dark:to-neutral-900 border border-neutral-200/50 dark:border-neutral-700/50">
            <h3 className="text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-3">Statistiques rapides</h3>
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-xs text-neutral-500 dark:text-neutral-400">Utilisateurs actifs</span>
                <span className="text-sm font-medium text-neutral-900 dark:text-white">1,234</span>
              </div>
              {/* Ajouter d'autres stats */}
            </div>
          </div>
        </nav>

        {/* Logout Button */}
        <div className="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50">
          <button
            onClick={onLogout}
            className="flex items-center justify-center space-x-2 w-full px-4 py-3 rounded-xl border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
          >
            <LogOut className="h-5 w-5" />
            <span>Déconnexion</span>
          </button>
        </div>
      </div>
    </aside>
  );
};

const SidebarItem = ({ to, icon, label, active, badge, badgeColor }) => (
  <li>
    <Link 
      to={to} 
      className={`flex items-center space-x-3 px-4 py-3 rounded-xl ${active ? 'bg-gradient-to-r from-primary-500 to-primary-600 text-white font-medium' : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800/50 transition-colors'}`}
    >
      {icon}
      <span>{label}</span>
      {badge && (
        <span className={`ml-auto px-2 py-1 text-xs font-medium bg-${badgeColor}-500 text-white rounded-full`}>
          {badge}
        </span>
      )}
    </Link>
  </li>
);

export default Sidebar;
